CREATE TABLE `anomalies` (\n  `id` int NOT NULL AUTO_INCREMENT,\n  `race_id` int DEFAULT NULL,\n  `runner_id` int DEFAULT NULL,\n  `detected_at` datetime DEFAULT NULL,\n  `reason` varchar(255) DEFAULT NULL,\n  `score` float DEFAULT NULL,\n  `lat` float DEFAULT NULL,\n  `lng` float DEFAULT NULL,\n  `resolved` tinyint(1) DEFAULT NULL,\n  PRIMARY KEY (`id`),\n  KEY `ix_anomalies_id` (`id`)\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci
CREATE TABLE `checkpoints` (\n  `id` int NOT NULL AUTO_INCREMENT,\n  `race_id` int DEFAULT NULL,\n  `name` varchar(100) DEFAULT NULL,\n  `lat` float DEFAULT NULL,\n  `lng` float DEFAULT NULL,\n  `radius_meters` int DEFAULT NULL,\n  `order_number` int DEFAULT NULL,\n  `type` varchar(20) DEFAULT 'timing',\n  PRIMARY KEY (`id`),\n  KEY `ix_checkpoints_id` (`id`)\n) ENGINE=InnoDB AUTO_INCREMENT=88 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci
CREATE TABLE `race_checkin_qr` (\n  `id` int NOT NULL AUTO_INCREMENT,\n  `race_id` int NOT NULL,\n  `qr_payload` varchar(255) NOT NULL,\n  `created_at` datetime DEFAULT NULL,\n  PRIMARY KEY (`id`),\n  UNIQUE KEY `race_id` (`race_id`),\n  KEY `ix_race_checkin_qr_id` (`id`),\n  CONSTRAINT `race_checkin_qr_ibfk_1` FOREIGN KEY (`race_id`) REFERENCES `races` (`id`)\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci
CREATE TABLE `race_results` (\n  `id` int NOT NULL AUTO_INCREMENT,\n  `race_id` int NOT NULL,\n  `runner_id` int NOT NULL,\n  `rank` int NOT NULL,\n  `distance_metres` float DEFAULT NULL,\n  `distance_km` float DEFAULT NULL,\n  `pace_min_per_km` float DEFAULT NULL,\n  `pace_formatted` varchar(20) DEFAULT NULL,\n  `finished_at` datetime DEFAULT NULL,\n  `segment` varchar(20) DEFAULT NULL,\n  PRIMARY KEY (`id`),\n  KEY `race_id` (`race_id`),\n  KEY `runner_id` (`runner_id`),\n  KEY `ix_race_results_id` (`id`),\n  CONSTRAINT `race_results_ibfk_1` FOREIGN KEY (`race_id`) REFERENCES `races` (`id`),\n  CONSTRAINT `race_results_ibfk_2` FOREIGN KEY (`runner_id`) REFERENCES `users` (`id`)\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci
CREATE TABLE `race_runners` (\n  `id` int NOT NULL AUTO_INCREMENT,\n  `race_id` int NOT NULL,\n  `runner_id` int NOT NULL,\n  `registered_at` datetime DEFAULT NULL,\n  `city` varchar(100) DEFAULT NULL,\n  `contact_number` varchar(30) DEFAULT NULL,\n  `is_first_marathon` tinyint(1) DEFAULT NULL,\n  `emergency_contact` varchar(100) DEFAULT NULL,\n  `sex` enum('male','female','prefer_not_to_say') DEFAULT NULL,\n  `qr_token` varchar(100) DEFAULT NULL,\n  `is_present` tinyint(1) DEFAULT NULL,\n  `checked_in_at` datetime DEFAULT NULL,\n  `shirt_size` varchar(10) NOT NULL DEFAULT 'M',\n  `bib_number` int DEFAULT NULL,\n  `claimed` tinyint(1) DEFAULT '0',\n  `claimed_at` datetime DEFAULT NULL,\n  `is_walkin` tinyint(1) DEFAULT '0',\n  `walkin_name` varchar(100) DEFAULT NULL,\n  `walkin_contact` varchar(30) DEFAULT NULL,\n  `race_status` varchar(20) DEFAULT 'registered',\n  PRIMARY KEY (`id`),\n  UNIQUE KEY `ix_race_runners_qr_token` (`qr_token`),\n  KEY `race_id` (`race_id`),\n  KEY `runner_id` (`runner_id`),\n  KEY `ix_race_runners_id` (`id`),\n  CONSTRAINT `race_runners_ibfk_1` FOREIGN KEY (`race_id`) REFERENCES `races` (`id`),\n  CONSTRAINT `race_runners_ibfk_2` FOREIGN KEY (`runner_id`) REFERENCES `users` (`id`)\n) ENGINE=InnoDB AUTO_INCREMENT=27 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci
CREATE TABLE `races` (\n  `id` int NOT NULL AUTO_INCREMENT,\n  `name` varchar(100) NOT NULL,\n  `distance_km` float NOT NULL,\n  `category` varchar(20) DEFAULT NULL,\n  `status` varchar(20) DEFAULT NULL,\n  `description` text,\n  `location` varchar(255) DEFAULT NULL,\n  `sponsors` text,\n  `max_participants` int DEFAULT NULL,\n  `scheduled_start` datetime DEFAULT NULL,\n  `registration_fee` float DEFAULT NULL,\n  `banner_url` varchar(500) DEFAULT NULL,\n  `created_at` datetime DEFAULT NULL,\n  PRIMARY KEY (`id`),\n  KEY `ix_races_id` (`id`)\n) ENGINE=InnoDB AUTO_INCREMENT=21 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci
CREATE TABLE `runner_checkpoints` (\n  `id` int NOT NULL AUTO_INCREMENT,\n  `runner_id` int DEFAULT NULL,\n  `checkpoint_id` int DEFAULT NULL,\n  `passed_at` datetime DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (`id`),\n  UNIQUE KEY `runner_id` (`runner_id`,`checkpoint_id`),\n  KEY `ix_runner_checkpoints_id` (`id`)\n) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci
CREATE TABLE `staff_assignments` (\n  `id` int NOT NULL AUTO_INCREMENT,\n  `user_id` int NOT NULL,\n  `race_id` int NOT NULL,\n  `assigned_at` datetime DEFAULT NULL,\n  `is_active` tinyint(1) DEFAULT NULL,\n  PRIMARY KEY (`id`),\n  KEY `user_id` (`user_id`),\n  KEY `race_id` (`race_id`),\n  KEY `ix_staff_assignments_id` (`id`),\n  CONSTRAINT `staff_assignments_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`),\n  CONSTRAINT `staff_assignments_ibfk_2` FOREIGN KEY (`race_id`) REFERENCES `races` (`id`)\n) ENGINE=InnoDB AUTO_INCREMENT=22 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci
CREATE TABLE `users` (\n  `id` int NOT NULL AUTO_INCREMENT,\n  `name` varchar(100) DEFAULT NULL,\n  `email` varchar(100) DEFAULT NULL,\n  `password` varchar(255) DEFAULT NULL,\n  `role` enum('runner','organizer','race_director','kit_staff','checkin_staff') DEFAULT 'runner',\n  `date_of_birth` date DEFAULT NULL,\n  PRIMARY KEY (`id`),\n  UNIQUE KEY `ix_users_email` (`email`),\n  KEY `ix_users_id` (`id`)\n) ENGINE=InnoDB AUTO_INCREMENT=37 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci